from pathlib import Path
import json,html,hashlib,csv
import numpy as np
import h5py
root=Path('results/extra45_activity_report');s=json.loads((root/'summary.json').read_text());m=json.loads((root/'manifest.json').read_text())
figures=[('Channel rates and concentration','channel_rates'),('Activity over time','timecourse'),('extra_4 full raster','extra4_raster'),('extra_5 full raster','extra5_raster'),('Channel activity heatmap','channel_time_heatmap'),('extra_5 coincidence close-up','extra5_coincidence_zoom'),('extra_4 trace examples','extra4_trace_examples'),('extra_4 waveform overlays','extra4_waveform_overlays'),('extra_5 trace examples','extra5_trace_examples'),('extra_5 waveform overlays','extra5_waveform_overlays'),('Amplitude and coverage','amplitude_quality')]
rows=[('Candidate count','115,992','173,029'),('Channels with candidates','1,578','2,042'),('Usable channel-time','98.66%','98.88%'),('Candidates / usable channel-second','0.191','0.285'),('Median channel rate / usable second','0.00667','0.09274'),('Candidate share on top 205 channels','90.7%','69.4%'),('Candidate share in five busiest 1 s bins','3.1%','17.1%'),('Largest number of channels in a 1 ms bin','236','1,479')]
body='''<h1>Extracellular candidate activity: extra_4 and extra_5</h1><p>20 November 2026 · 2,048 channels · 300 nominal seconds per recording</p><p><strong>Interpretation:</strong> These are detected electrode-level candidates, not confirmed eAPs or sorted neurons. extra_5 followed current-injection experiments; differences do not establish a causal stimulation effect. All saved candidates are included, including shared-warning events.</p><h2>Summary</h2><table><tr><th>Metric</th><th>extra_4</th><th>extra_5</th></tr>'''
body+=''.join('<tr>'+''.join(f'<td>{html.escape(v)}</td>' for v in row)+'</tr>' for row in rows)+'</table>'
body+='''<h2>What stands out</h2><p>extra_4 activity is concentrated on fewer channels. extra_5 has a larger background of detected events and pronounced widespread episodes. Its five busiest seconds contain 17.1% of all candidates. The largest 1 ms coincidence is at 276.887–276.888 s and involves 1,479 channels; this interval is unassessed by the existing shared-disturbance flags. Synchrony alone does not prove artifact or neural origin.</p><h2>Methods and limitations</h2><p>MA50 baseline subtraction; adaptive per-second MAD with an across-channel median floor; threshold multiplier 5; negative peaks; 5 ms spacing. Rates divide candidate counts by actual usable channel-seconds after flat guards and invalid noise-window exclusions. Nominal rate is 10,000 Hz; physical rate 10,080 Hz. No spatial mapping or neuron matching is assumed.</p><p>Shared-warning assessment covers 35/300 seconds per recording. Color saturation in the heatmap is a display choice at the pooled 99th percentile (4.20 candidates/s); no events are excluded by that display. Peak/threshold ratio is not an independent SNR estimate.</p><p>Trace examples use channels closest to the 25th, 50th and 90th rate percentiles among channels with at least 30 candidates and 270 usable seconds. Traces are centered on an event nearest 150 s. Overlays use up to 40 evenly spaced eligible events by order, not waveform appearance. All sample indices are saved in manifest.json and NPZ files. Peak alignment itself creates a central trough and does not establish spike identity.</p>'''
for title,stem in figures:body+=f'<section><h2>{title}</h2><img src="figures/{stem}.png" alt="{title}"><p><a href="figures/{stem}.pdf">Vector PDF</a> · <a href="figures/{stem}.png">PNG</a></p></section>'
body+='''<h2>Recommended next step</h2><p>Review raw signals around extra_5's large episodes (154–155 s and 276.887 s), then extend shared-disturbance assessment across both complete recordings before deciding whether to exclude events. Preserve the detected candidates and quality-aware exposure. Apply verified electrode geometry before spatial analysis; defer neuron-level conclusions until sorting or spatial deduplication.</p><h2>Files and reproduction</h2><p>summary.json: metrics; tables/: per-channel rates, 1 s timecourses and 1 ms coincidence counts; figures/: PNG/PDF; NPZ: exact selected waveform arrays; manifest.json: input hashes and selection identities. Run <code>.venv/bin/python analysis/activity_report.py</code> from the repository. Original source drive is needed to regenerate waveforms.</p>'''
(root/'report.html').write_text('<!doctype html><meta charset="utf-8"><title>extra_4 / extra_5 activity</title><style>body{font:17px system-ui;max-width:1150px;margin:40px auto;padding:0 25px;color:#243649;line-height:1.55}h1,h2{color:#123047}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #ddd}th{background:#edf3f6}img{width:100%;height:auto}section{margin-top:45px}a{color:#167d9a}</style>'+body)
checks={}
for rec in [4,5]:
 info=m['inputs'][str(rec)];assert hashlib.sha256(Path(info['path']).read_bytes()).hexdigest()==info['sha256']
 with h5py.File(info['path'],'r') as f:
  assert len(f['spikes/sample_index'])==s[str(rec)]['candidates']
  with open(root/'tables'/f'extra{rec}_channels.csv') as fp:channels=list(csv.DictReader(fp))
  with open(root/'tables'/f'extra{rec}_timecourse.csv') as fp:times=list(csv.DictReader(fp))
  assert sum(int(r['candidate_count']) for r in channels)==s[str(rec)]['candidates']
  assert sum(int(r['candidate_count']) for r in times)==s[str(rec)]['candidates']
  assert abs(sum(float(r['usable_seconds']) for r in channels)-s[str(rec)]['usable_channel_seconds'])<1e-5
 checks[str(rec)]={'event_total_and_exposure_reconciled':True,'input_hash_verified':True,'source_metadata_verified_during_analysis':True,'overlay_peak_amplitudes_checked_against_saved_events':True}
assert hashlib.sha256(Path('analysis/activity_report.py').read_bytes()).hexdigest()==m['analysis_code_sha256']
(root/'validation.json').write_text(json.dumps(checks,indent=2)+'\n')
(root/'presentation.json').write_text(json.dumps({'page_id':'page_dbff7fe3b7bc81919c66c50882a6bfd5','artifact_ref':'artifact_external_cbccd370-3874-439d-8f75-02c1defebbcd','title':'Extracellular activity — extra_4 and extra_5','slide_count':15,'download':'Export as PowerPoint (.pptx) from the presentation viewer'},indent=2)+'\n')
print('Report saved; source hashes, counts, exposures and selected waveform peaks verified.')
